'use strict';

// MAIN //

var valid = [];

valid.push({
	'code': [
		'var floor = require( \'@stdlib/math/base/special/floor\' );',
		'var y = floor( 3.14 );'
	].join( '\n' )
});

valid.push({
	'code': [
		'var dcopy = require( \'@stdlib/blas/base/dcopy\' );',
		'var type = typeof dcopy;',
		'dcopy.ndarray( x.length, x, 1, 0, y, 1, 0 );'
	].join( '\n' )
});

valid.push({
	'code': [
		'var x = require( \'foo\' );',
		'x.a();',
		'x.b();'
	].join( '\n' )
});

valid.push({
	'code': [
		'var x = require( \'foo\' );',
		'x[ k ]();'
	].join( '\n' )
});

valid.push({
	'code': [
		'var x = require( \'foo\' );',
		'f( x );'
	].join( '\n' )
});

valid.push({
	'code': [
		'var x = require( \'foo\' );',
		'module.exports = x;'
	].join( '\n' )
});

valid.push({
	'code': [
		'var dcopy = require( \'@stdlib/blas/base/dcopy\' ).ndarray;',
		'dcopy( x.length, x, 1, 0, y, 1, 0 );'
	].join( '\n' )
});

valid.push({
	'code': [
		'var x = require( \'foo\' );',
		'x.foo = 1;',
		'x.foo();'
	].join( '\n' )
});

valid.push({
	'code': [
		'var x = require( \'foo\' );',
		'x = other;',
		'x.foo();'
	].join( '\n' )
});

valid.push({
	'code': [
		'var x = require( \'foo\' );',
		'var str = \'\' + x;'
	].join( '\n' )
});

valid.push({
	'code': [
		'var x = require( \'foo\' );',
		'delete x.foo;',
		'x.foo();'
	].join( '\n' )
});

valid.push({
	'code': [
		'var x = require( \'foo\' );',
		'x.count += 1;',
		'var v = x.count;'
	].join( '\n' )
});

valid.push({
	'code': 'var x = require( \'foo\' );'
});

valid.push({
	'code': [
		'function f() {',
		'\tvar x = require( \'foo\' );',
		'\treturn x.bar();',
		'}'
	].join( '\n' )
});


// EXPORTS //

module.exports = valid;
